# ══ LEVEL-1 ══
q(1, 8, 'కింది పద్యానికి ప్రతిపదార్థాలు రాయండి.\nఎంతయు వృద్ధులై తమకు నీ వొకరుండవ తెప్ప గాఁగ న\nత్యంతముదంబునన్ బ్రదుకు తల్లిని దండ్రిని నుజ్జగించి ని\nశ్చింతుఁడవై సదాధ్యయనశీలత వారి యనుజ్ఞ లేక యే\nకాంతమ యెమ్మెయిన్ వెడలి తక్కట! నీవు గరంబు క్రూరతన్.',
  'ప్రతిపదార్థం:\nఎంతయున్ = మిక్కిలి\nవృద్ధులు + ఐ = ముసలివారై\nతమకున్ = తమకు\nనీవు ఒకరుండవ = నీవు ఒక్కడివే\nతెప్ప గాఁగన్ = ఆధారంగా (దిక్కుగా)\nఅత్యంత ముదంబునన్ = ఎంతో సంతోషంతో\nబ్రదుకు = జీవిస్తున్న\nతల్లిని దండ్రిని = తల్లిని, తండ్రిని\nఉజ్జగించి = విడిచిపెట్టి\nనిశ్చింతుఁడవు + ఐ = ఏ విచారమూ లేనివాడివై\nసదా = ఎల్లప్పుడూ\nఅధ్యయనశీలతన్ = వేదాలు చదువుకోవాలనే స్వభావంతో\nవారి యనుజ్ఞ లేక = వారి అనుమతి లేకుండా\nఏకాంతము + అ = ఒంటరిగానే\nఏ మెయిన్ = ఏ విధంగా\nవెడలితి = బయలుదేరి వచ్చావు\nఅక్కట = అయ్యో!\nనీవు = నువ్వు\nకరంబు = మిక్కిలి\nక్రూరతన్ = కఠినత్వంతో (ప్రవర్తించావు)\nభావం: కౌశికా! బాగా ముసలివారై, నువ్వొక్కడివే తమకు ఆధారంగా సంతోషంగా జీవిస్తున్న తల్లిదండ్రులను విడిచిపెట్టి, వారి అనుమతి లేకుండా చదువుపై కోరికతో ఒంటరిగా ఎలా వచ్చావు? అయ్యో! నువ్వు చాలా కఠినంగా ప్రవర్తించావు.')
q(1, 8, 'ప్రత్యక్ష దైవాలు పాఠం సారాంశాన్ని మీ సొంత మాటల్లో రాయండి.',
  'కవి పరిచయం: ఈ పాఠం ఎఱ్ఱన రచించిన మహాభారతం అరణ్యపర్వం (5వ ఆశ్వాసం) నుండి గ్రహించబడింది.\nసారాంశం:\n• అరణ్యవాసంలో ఉన్న ధర్మరాజుకు మార్కండేయ మహర్షి కౌశికుని కథ చెప్పాడు.\n• కౌశికుడు అనే బ్రాహ్మణుడు వృద్ధులైన తల్లిదండ్రుల అనుమతి లేకుండా వేదాధ్యయనానికి వెళ్ళిపోయాడు.\n• ఒక పతివ్రత సూచనతో ధర్మసూక్ష్మాలు తెలుసుకోవడానికి మిథిలా నగరంలోని ధర్మవ్యాధుని దగ్గరకు వచ్చాడు.\n• ధర్మవ్యాధుడు అతనిని ఆదరించి తన ఇంటికి తీసుకువెళ్ళాడు. సంతోషంగా ఉన్న తన తల్లిదండ్రులను చూపించి “వీరే నా ప్రత్యక్ష దైవాలు” అన్నాడు. వారికి ఇష్టమైన పండ్లు, పూలు, వస్త్రాలు, ఆభరణాలు, భక్ష్యభోజ్యాలు సమర్పించి భార్యాబిడ్డలతో సేవ చేస్తానని చెప్పాడు.\n• తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మ – ఈ ఐదుగురిని సంతోషపెట్టే గృహస్థుడే ధర్మాత్ముడని తెలిపాడు.\n• “నువ్వు చెప్పకుండా వెళ్ళిపోవడంతో నీ తల్లిదండ్రులు ఏడ్చి ఏడ్చి కళ్ళు కనిపించకుండా పోయారు. వారి అనుమతి లేని నీ అధ్యయనం, శ్రమ వ్యర్థం. వెంటనే వెళ్ళి వారిని సేవించు” అని హితవు చెప్పాడు.\n• కౌశికుడు తన తప్పు తెలుసుకుని, ఇంటికి వెళ్ళి తల్లిదండ్రులను సేవిస్తానని మాట ఇచ్చాడు.\nసందేశం: తల్లిదండ్రుల సేవను మించిన ధర్మం లేదు; వారే మనకు ప్రత్యక్ష దైవాలు.')
q(1, 8, 'కౌశికుడు – ధర్మవ్యాధుల వృత్తాంతాన్ని సంభాషణ రూపంలో రాయండి.',
  'ధర్మవ్యాధుడు: రండి మహాత్మా! పతివ్రత పంపగా ధర్మం తెలుసుకోవడానికి మీరు నా దగ్గరకు వచ్చారని నాకు తెలుసు.\nకౌశికుడు: (ఆశ్చర్యంతో) నేను వచ్చిన పని మీకెలా తెలిసింది? దయచేసి నాకు ధర్మసూక్ష్మాలు చెప్పండి.\nధర్మవ్యాధుడు: ముందు మా ఇంటికి రండి. (ఇంట్లోకి తీసుకువెళ్ళి) చూడండి, వీరే నా తల్లిదండ్రులు – నా ప్రత్యక్ష దైవాలు.\nకౌశికుడు: వారు ఎంతో ఆనందంగా ఉన్నారు!\nధర్మవ్యాధుడు: వారికి ఇష్టమైన పండ్లు, పూలు, గంధం, వస్త్రాలు, ఆభరణాలు, భక్ష్యభోజ్యాలు సమర్పిస్తాను. నా భార్యాబిడ్డలతో కలిసి సేవిస్తాను. తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మ – ఈ ఐదుగురిని సంతోషపెట్టేవాడే ధర్మాత్ముడు. ఈ సేవ వల్లే నాకు జ్ఞానం లభించింది.\nకౌశికుడు: మీ మాటలు నా మనసును తాకాయి.\nధర్మవ్యాధుడు: కౌశికా! నువ్వు ఒక్కడివే ఆధారంగా జీవిస్తున్న ముసలి తల్లిదండ్రులను వారి అనుమతి లేకుండా విడిచి వచ్చావు. వారు నీ కోసం ఏడ్చి ఏడ్చి కళ్ళు పోగొట్టుకున్నారు. వారి అనుమతి లేని అధ్యయనం వ్యర్థం. వెంటనే వెళ్ళి వారి దుఃఖాగ్నిని చల్లార్చు.\nకౌశికుడు: నా తప్పు తెలుసుకున్నాను. ఇప్పుడే ఇంటికి వెళ్ళి జీవితాంతం నా తల్లిదండ్రులను సేవిస్తాను. మీకు నమస్కారం.')
q(1, 4, 'ప్రత్యక్ష దైవాలు – పాఠ్యభాగ కవి జీవిత విశేషాలను తెలియజేయండి.',
  '• కవి: ఎఱ్ఱన (ఎఱ్ఱాప్రగడ) – క్రీ.శ. 14వ శతాబ్దం; కవిత్రయంలో మూడవవాడు.\n• తల్లిదండ్రులు: పోతమాంబ, సూరనార్యుడు; జన్మస్థలం: గుడ్లూరు (పాకనాడు – నేటి ప్రకాశం జిల్లా).\n• ప్రోలయ వేమారెడ్డి ఆస్థాన కవి.\n• బిరుదులు: శంభుదాసుడు, ప్రబంధ పరమేశ్వరుడు.\n• రచనలు: ఆంధ్ర మహాభారతంలో అరణ్యపర్వ శేషం, హరివంశం, రామాయణం, నృసింహపురాణం.\n• శైలి: సూక్తివైచిత్రి, వర్ణనా నైపుణ్యం; నన్నయ, తిక్కనల శైలులను సమన్వయం చేశాడు.')
m(1, 'జనకుడు తన పిల్లలను చక్కగా తీర్చిదిద్దాలి. (గీత గీసిన పదం: జనకుడు) సరైన అర్థం గుర్తించండి.', ['జనని', 'తండ్రి', 'అమ్మ', 'గురువు'], 1, mk=2)
m(1, 'దేవతలు అమృతం సేవించడం వల్ల అమరులు అయ్యారు. (గీత గీసిన పదం: అమరులు) సరైన అర్థం గుర్తించండి.', ['మానవులు', 'మరణం లేనివారు', 'రాక్షసులు', 'మరణం ఉన్నవారు'], 1, mk=2)
for w, a in [('భూషణం', 'ఆభరణం, అలంకారం'), ('వాంఛ', 'కోరిక'), ('హర్మ్యాలు', 'మేడలు, భవనాలు'), ('హితము', 'మేలు, మంచి')]:
    q(1, 2, f'‘{w}’ {AR}', a)
m(1, 'జనని జనకులు సదా పూజనీయులు. (గీత గీసిన పదం: జనని) పర్యాయపదాలు గుర్తించండి.', ['తల్లి, మాత', 'మాత, మమత', 'అమ్మ, నాన్న', 'కూతురు, కొడుకు'], 0, mk=2)
m(1, 'పుత్రుడు యొక్క అభివృద్ధిని తండ్రి కోరుకుంటాడు. (గీత గీసిన పదం: పుత్రుడు) సరైన పర్యాయపదాలు గుర్తించండి.', ['కొడుకు, కుమారుడు', 'తాత, నాన్న', 'కుమారుడు, తండ్రి', 'తల్లి, అమ్మ'], 0, mk=2)
for w, a in [('వస్త్రం', 'బట్ట, వసనం, అంబరం, చేలం'), ('చక్షువు', 'కన్ను, నేత్రం, నయనం, లోచనం'), ('వహ్ని', 'అగ్ని, అనలం, పావకుడు, నిప్పు')]:
    q(1, 2, f'‘{w}’ {PY}', a)
m(1, 'విద్యార్థులు విన్నాణంను సంపాదించుకోవాలి. (గీత గీసిన పదం: విన్నాణం) ప్రకృతి పదం గుర్తించండి.', ['విజ్ఞానం', 'తెలివి', 'పరిజ్ఞానం', 'వినోదం'], 0, mk=2)
m(1, 'కష్ట సమయాల్లో హృదయాన్ని దృఢంగా వుంచుకోవాలి. (గీత గీసిన పదం: హృదయం) వికృతి పదం గుర్తించండి.', ['ఎద', 'దిటవు', 'కస్తి', 'గట్టిగా'], 0, mk=2)
for w, a in [('యజ్ఞం', 'యజ్ఞం (ప్రకృతి) – జన్నం (వికృతి)'), ('కార్యం', 'కార్యం (ప్రకృతి) – కర్జం (వికృతి)'), ('పుత్రుడు', 'పుత్రుడు (ప్రకృతి) – బొట్టె (వికృతి)'), ('హృదయం', 'హృదయం (ప్రకృతి) – ఎద, ఎడద (వికృతి)')]:
    q(1, 2, f'‘{w}’ {PV}', a)
m(1, 'గురువును గౌరవించవలెను. (గీత గీసిన పదం: గురువు) సరైన నానార్థాలు గుర్తించండి.', ['ఒజ్జ, ఉపాధ్యాయుడు', 'తండ్రి, బృహస్పతి', 'అధ్యాపకుడు, జనని', 'గ్రహం, నక్షత్రం'], 1, 'గురువు = ఉపాధ్యాయుడు, తండ్రి, బృహస్పతి, పెద్ద. (‘ఒజ్జ, ఉపాధ్యాయుడు’ పర్యాయపదాలు – ఒకే అర్థం.)', mk=2)
m(1, 'అర్థములు నిత్యము కావు. (గీత గీసిన పదం: అర్థము) సరైన నానార్థాలు గుర్తించండి.', ['సంపద, మాట', 'ధనం, కోట', 'సంపద, శబ్దార్థం', 'శబ్దార్థం, శతాబ్దం'], 2, 'అర్థము = ధనం (సంపద), శబ్దార్థం, ప్రయోజనం, కారణం.', mk=2)
for w, a in [('ఫలం', 'పండు, ప్రయోజనం, లాభం'), ('బుధుడు', 'పండితుడు, బుధగ్రహం, దేవత'), ('వంశం', 'కులం, వెదురు, సమూహం')]:
    q(1, 2, f'‘{w}’ {NN}', a)
q(1, 2, 'అలంకారాన్ని గుర్తించి, లక్షణం రాయండి: “సంసారసాగరాన్ని ఈదటం కష్టం.”', 'రూపకాలంకారం.\nలక్షణం: ఉపమేయానికి, ఉపమానానికి భేదం ఉన్నా లేనట్లు (అభేదం) చెప్పడం రూపకాలంకారం.\nసమన్వయం: ఉపమేయం – సంసారం, ఉపమానం – సాగరం (సముద్రం). సంసారమే సాగరం అని అభేదం చెప్పడం వల్ల రూపకాలంకారం.')
q(1, 2, 'అలంకారాన్ని గుర్తించి, లక్షణం రాయండి: “ప్రభుత్వం రైతులపై దయావర్షం కురిపించింది.”', 'రూపకాలంకారం.\nలక్షణం: ఉపమేయ, ఉపమానాలకు అభేదం చెప్పడం.\nసమన్వయం: ఉపమేయం – దయ, ఉపమానం – వర్షం. దయనే వర్షంగా అభేదం చెప్పారు.')
m(1, 'కాశ్మీర్ అత్యంత సుందరముగా ఉంది. (గీత గీసిన పదం: అత్యంత) విడదీసి గుర్తించండి.', ['అత్య + ఎంత', 'అత్య + అంత', 'అతి + అంత', 'ఆ + త్యం'], 2, 'అతి + అంత = అత్యంత – యణాదేశ సంధి (ఇ కారానికి అసవర్ణ అచ్చు పరమైతే య కారం).')
m(1, 'కింది పదాలలో ‘ఉత్వసంధి’కి చెందిన పదాన్ని గుర్తించండి.', ['సురైక', 'ఉత్తరోత్తర', 'మహాత్మ', 'కలదొక'], 3, 'కలదు + ఒక = కలదొక – ఉత్తునకు అచ్చు పరమైతే సంధి.')
m(1, 'ధర్మరాజును అందరూ ధర్మాత్ముడు అని అంటారు. (గీత గీసిన పదం: ధర్మాత్ముడు) ఏ సంధి?', ['సవర్ణదీర్ఘసంధి', 'అత్వసంధి', 'ఉత్వసంధి', 'గుణసంధి'], 0, 'ధర్మ + ఆత్ముడు – అ + ఆ = ఆ – సవర్ణదీర్ఘ సంధి.')
for w, a in [('నిజంబగు', 'నిజంబు + అగు – ఉత్వ సంధి'), ('మూలంబైనది', 'మూలంబు + ఐనది – ఉత్వ సంధి'), ('కలదొక', 'కలదు + ఒక – ఉత్వ సంధి'), ('వేల్పులనఘ', 'వేల్పులు + అనఘ – ఉత్వ సంధి'), ('నీవొకరుండవు', 'నీవు + ఒకరుండవు – ఉత్వ సంధి')]:
    q(1, 1, f'‘{w}’ {SD}', a)
m(1, 'జననీజనకులు సదా పూజనీయులు. (గీత గీసిన పదం: జననీజనకులు) విగ్రహ వాక్యం గుర్తించండి.', ['జనాలును, జనకులును', 'జలజను, జనకుడును', 'జననియును, జనకుడును', 'జన్మనిచ్చినవారు'], 2, 'ద్వంద్వ సమాసం.')
m(1, 'అందరూ ధర్మపథంలో నడవాలి. (గీత గీసిన పదం: ధర్మపథం) ఏ సమాసం?', ['ద్వంద్వ సమాసం', 'షష్ఠీ తత్పురుష సమాసం', 'రూపక సమాసం', 'విశేషణ పూర్వపద కర్మధారయ సమాసం'], 1, 'ధర్మము యొక్క పథము – షష్ఠీ తత్పురుష.')
for w, a in [('ఫలపుష్పములు', 'ఫలములును, పుష్పములును – ద్వంద్వ సమాసం'), ('వస్త్రభూషణములు', 'వస్త్రములును, భూషణములును – ద్వంద్వ సమాసం'), ('భక్ష్యభోజ్యములు', 'భక్ష్యములును, భోజ్యములును – ద్వంద్వ సమాసం')]:
    q(1, 1, f'‘{w}’ {SM}', a)
for s, a in [('ధర్మవ్యాధుండు కౌశికునితో యిట్లనియె.', 'ధర్మవ్యాధుడు కౌశికునితో ఇలా అన్నాడు.'), ('గృహంబునకు రమ్మని యతనిం దోడ్కొని చనియె.', 'ఇంటికి రమ్మని అతనిని తీసుకొని వెళ్ళాడు.'),
             ('ఇమ్మహాత్ముండు మనలన్ జూచువేడ్క నిటవచ్చెనని చెప్పిన.', 'ఈ మహాత్ముడు మనలను చూడాలనే కోరికతో ఇక్కడికి వచ్చాడని చెప్పగా.'), ('పతివ్రత పనుపునం జేసి నీవు ధర్మజ్ఞానార్థంబు నాయున్నయెడకుం జనుదెంచితివి.', 'పతివ్రత పంపడం వల్ల నువ్వు ధర్మం తెలుసుకోవడం కోసం నేను ఉన్న చోటుకు వచ్చావు.')]:
    q(1, 1, f'ఆధునిక వచనంలోకి మార్చి రాయండి: “{s}”', a)
# ══ LEVEL-2 ══
q(2, 8, 'కింది పద్యానికి ప్రతిపదార్థాలు రాయండి.\nఅనుపమ మెట్టివారలకు నందదు ధర్మపథంబు ధాత్రిలో;\nవిను, పది వేవురందొకఁడు విశ్రుతధర్మపరాయణుండు గ\nల్గునొ కలుగండొ సందియము; గోరి సనాతనధర్మమూఁది యె\nవ్వనికిని నీకుఁ బోలె బుధ వత్సల! యిట్లు చరింపవచ్చునే.',
  'ప్రతిపదార్థం:\nబుధవత్సల = పండితుల పట్ల ప్రేమ గలవాడా! (ధర్మవ్యాధా!)\nవిను = వినుము\nధాత్రిలోన్ = భూమిపై\nధర్మపథంబు = ధర్మమార్గం\nఅనుపమము = సాటిలేనిది\nఎట్టివారలకున్ = ఎంతటివారికైనా\nఅందదు = అందదు (సులభంగా లభించదు)\nపదివేవురందున్ = పదివేల మందిలో\nఒకఁడు = ఒక్కడు\nవిశ్రుత ధర్మపరాయణుండు = ప్రసిద్ధుడైన ధర్మాచరణంలో ఆసక్తి గలవాడు\nకల్గునొ కలుగండొ = ఉంటాడో ఉండడో\nసందియము = సందేహమే\nకోరి = ఇష్టపడి\nసనాతన ధర్మము + ఊఁది = శాశ్వతమైన ధర్మాన్ని ఆధారంగా చేసుకొని\nనీకుఁ బోలె = నీ వలె\nఎవ్వనికిని = ఎవరికైనా\nఇట్లు = ఈ విధంగా\nచరింపవచ్చునే = ప్రవర్తించడం సాధ్యమా? (సాధ్యం కాదు)\nభావం: ఓ ధర్మవ్యాధా! ఈ లోకంలో ధర్మమార్గం సాటిలేనిది; అది ఎంతటివారికీ సులభంగా అందదు. పదివేల మందిలో ఒక్కడైనా గొప్ప ధర్మపరుడు ఉంటాడో లేదో సందేహమే. నీలాగా ఇష్టపడి సనాతనధర్మాన్ని ఆశ్రయించి ఇలా ప్రవర్తించడం ఎవరికి సాధ్యం?')
q(2, 8, 'ప్రత్యక్ష దైవాలు పాఠం ఆధారంగా ధర్మవ్యాధుని వ్యక్తిత్వాన్ని విశ్లేషించండి.',
  '1) మాతృపితృ భక్తుడు: తల్లిదండ్రులనే ప్రత్యక్ష దైవాలుగా భావించాడు. వారికి ఇష్టమైన పండ్లు, పూలు, గంధం, వస్త్రాలు, ఆభరణాలు, భక్ష్యభోజ్యాలు సమర్పించి భార్యాబిడ్డలతో సహా సేవించేవాడు.\n2) జ్ఞాని: కులవృత్తి (మాంసం అమ్మడం) చేస్తున్నా ధర్మసూక్ష్మాలు తెలిసినవాడు; కౌశికుడు ఎవరి పంపున వచ్చాడో ముందే గ్రహించాడు.\n3) అతిథి మర్యాద తెలిసినవాడు: కౌశికుని ఆదరంగా ఇంటికి తీసుకువెళ్ళి గౌరవించాడు.\n4) ధర్మోపదేశకుడు: తల్లి, తండ్రి, గురువు, అగ్ని, ఆత్మ – ఈ ఐదుగురిని సంతోషపెట్టేవాడే ధర్మాత్ముడని తెలిపాడు.\n5) హితైషి: కౌశికుని తప్పును సూటిగా, సున్నితంగా చెప్పి, తల్లిదండ్రుల దగ్గరకు తిరిగి వెళ్ళమని హితవు చెప్పాడు.\n6) వినయశీలి: తనకు వచ్చిన జ్ఞానం అంతా తల్లిదండ్రుల సేవ ఫలితమే అన్నాడు.\nముగింపు: ధర్మవ్యాధుడు కులంతో కాక గుణంతో గొప్పవాడైన ఆదర్శ పుత్రుడు, ధర్మాత్ముడు.')
q(2, 8, 'వృద్ధాశ్రమాలు పెరిగిపోతున్న నేటిరోజుల్లో “తల్లిదండ్రుల సేవను మించిన ధర్మం లేదు” అనే ధర్మవ్యాధుని అభిప్రాయ ప్రాధాన్యతను పాఠం ఆధారంగా వివరించండి.',
  '• నేడు ఉద్యోగాలు, విదేశీ ప్రయాణాలు, స్వార్థం, చిన్న కుటుంబాల వల్ల చాలామంది వృద్ధులైన తల్లిదండ్రులను వృద్ధాశ్రమాల్లో చేరుస్తున్నారు.\n• ధర్మవ్యాధుడు తల్లిదండ్రులను ప్రత్యక్ష దైవాలుగా భావించి భార్యాబిడ్డలతో కలిసి సేవించాడు; ఆ సేవ వల్లే అతనికి జ్ఞానం, కీర్తి వచ్చాయి.\n• కౌశికుడు తల్లిదండ్రులను విడిచి వెళ్ళడంతో వారు ఏడ్చి ఏడ్చి చూపు కోల్పోయారు – తల్లిదండ్రులను నిర్లక్ష్యం చేస్తే వారికి ఎంతటి దుఃఖం కలుగుతుందో ఇది చూపుతుంది.\n• “తల్లిదండ్రుల అనుమతి లేని చదువు, శ్రమ వ్యర్థం” అన్న ధర్మవ్యాధుని మాట నేటి యువతకు గుణపాఠం.\n• మనల్ని కని, పెంచి, చదివించిన తల్లిదండ్రులకు వృద్ధాప్యంలో ప్రేమ, గౌరవం, ఆరోగ్య సంరక్షణ ఇవ్వడం పిల్లల కనీస బాధ్యత; ప్రభుత్వం కూడా వృద్ధ తల్లిదండ్రుల పోషణను పిల్లల బాధ్యతగా చట్టం చేసింది.\n• మన పిల్లలు మనల్ని చూసే నేర్చుకుంటారు – మనం తల్లిదండ్రులను సేవిస్తేనే రేపు మనకూ ఆ సేవ దక్కుతుంది.\nముగింపు: కాబట్టి “తల్లిదండ్రుల సేవను మించిన ధర్మం లేదు” అన్న ధర్మవ్యాధుని అభిప్రాయం నేటి సమాజానికి మరింత అవసరం; వృద్ధాశ్రమాలు అవసరం లేని సమాజం రావాలి.')
m(2, 'ఎవరూ ధర్మం తప్పి ప్రవర్తించరాదు. (గీత గీసిన పదం: ధర్మం) సరైన వ్యుత్పత్త్యర్థం గుర్తించండి.', ['జనులు మాట్లాడునది', 'లోకం అంతా సంచరించునది', 'విశ్వమును ధరించునది', 'ఆచరించబడేది'], 2, 'ధర్మం – లోకాన్ని (విశ్వాన్ని) ధరించునది.', mk=2)
m(2, 'వసుధ పై ఎన్నో జీవరాసులు జీవిస్తున్నాయి. (గీత గీసిన పదం: వసుధ) సరైన వ్యుత్పత్త్యర్థం గుర్తించండి.', ['సమస్తమును ధరించునది', 'జీవులకు నిలయమైనది', 'బంగారము గర్భమందు కలిగినది', 'చలనం కలిగినది'], 2, 'వసుధ – వసువు (బంగారం, ధనం) గర్భమందు కలది – భూమి.', mk=2)
for w, a in [('బుధుడు', 'తెలిసికొనువాడు (జ్ఞానం గలవాడు) – పండితుడు'), ('జనని', 'జన్మనిచ్చునది – తల్లి'), ('కౌశికుడు', 'కుశికుని వంశంలో పుట్టినవాడు')]:
    q(2, 2, f'‘{w}’ {VY}', a)
q(2, 2, 'పద్య పాదానికి గురు, లఘువులు గుర్తించి, గణ విభజన చేసి ఏ పద్య పాదమో రాయండి: “అనుపమ మెట్టి వారలకు నందదు ధర్మపథంబు ధాత్రిలో”',
  'అనుప | మమెట్టి | వారల | కునంద | దుధర్మ | పథంబు | ధాత్రిలో\nI I I | I U I | U I I | I U I | I U I | I U I | U I U\nన | జ | భ | జ | జ | జ | ర\nఇది చంపకమాల పద్యపాదం (న జ భ జ జ జ ర గణాలు; యతి – 11వ అక్షరం: అ – నం).')
q(2, 2, 'పద్య పాదానికి గురు, లఘువులు గుర్తించి, గణ విభజన చేసి ఏ పద్య పాదమో రాయండి: “ఎంతయు వృద్ధులై తమకు నీవొకరుండవ తెప్పగాఁగ న”',
  'ఎంతయు | వృద్ధులై | తమకు | నీవొక | రుండవ | తెప్పగా | ఁగన\nU I I | U I U | I I I | U I I | U I I | U I U | I U\nభ | ర | న | భ | భ | ర | వ\nఇది ఉత్పలమాల పద్యపాదం (భ ర న భ భ ర వ గణాలు; యతి – 10వ అక్షరం: ఎ – నీ).')
for w, a in [('జ్ఞానార్థంబు', 'జ్ఞాన + అర్థంబు – సవర్ణదీర్ఘ సంధి'), ('విజ్ఞానోన్నతి', 'విజ్ఞాన + ఉన్నతి – గుణ సంధి'), ('ఇమ్మెయి', 'ఈ + మెయి – త్రిక సంధి')]:
    q(2, 1, f'‘{w}’ {SD}', a)
for w, a in [('ధర్మపథము', 'ధర్మము యొక్క పథము – షష్ఠీ తత్పురుష సమాసం'), ('సనాతనధర్మం', 'సనాతనమైన ధర్మం – విశేషణ పూర్వపద కర్మధారయ సమాసం'), ('మానుషదేహం', 'మానుషమైన దేహం – విశేషణ పూర్వపద కర్మధారయ సమాసం'), ('శోకవహ్ని', 'శోకమనెడు వహ్ని – రూపక సమాసం')]:
    q(2, 1, f'‘{w}’ {SM}', a)
